// Active projects (lokalise_project_labels active = true) minus My QR Code html - same scope as the daily audit.
const EXCLUDE = ['18564477693fc9bba4cec8.54789459'];
function clean(n) { return String(n).split('"').join(''); }
const active = $('Read active projects').all().map(function (i) { return i.json; }).filter(function (r) { return String(r.active).toLowerCase() === 'true' && r.project_id && EXCLUDE.indexOf(r.project_id) === -1; });
if (!active.length) { throw new Error('No active projects in lokalise_project_labels'); }
const nowS = Math.floor(Date.now() / 1000);
return active.map(function (p) { return { json: { project_id: p.project_id, project_name: clean(p.project_name), since_ts: nowS - 14 * 86400 } }; });

const LINGUISTS = ['sabrathan@gmail.com', 'farahputri@gmail.com', 'dmluciahorea@gmail.com', 'roxanamoldovan25@gmail.com', 'mteres@terestraducciones.com', 'arandatrad@gmail.com', 'sara.guinot.trad@gmail.com', 'daniel@dgmultilingualservices.com', 'qrcodelocalization@gmail.com', 'root-translations@outlook.com', 'austra.muizniece@gmail.com', 'harald.roald@gmail.com', '47natcha@gmail.com', 'ellen.de.venter@outlook.com', 'ilaria.roncaglia@gmail.com', 'silke.luehrmann@gmx.de', 'boh.vozniuk@gmail.com', 'vidiasc@gmail.com', 'ivanaturcin@ymail.com', 'julius.valkiunas@gmail.com', 'jaromirvicari@me.com', 'karahansisman@gmail.com', 'katri.varvikko@gmail.com', 'kenneth@phraseit.dk', 'translation@cornell.hu', 'ruckova.lucia@gmail.com', 'marit.teichmann@gmail.com', 'michal.tosza@translators.org.pl', 'mteixeira@sacradomus.com', 'bruno@bsttranslations.com', 'nerissaneptuno@gmail.com', 'straus.translations@gmail.com', 'quentinnguyen.localize@gmail.com', 'therese.svardsten@gmail.com', 'mjlocalize@gmail.com', 'silis.martins@gmail.com', 'isengoz@gmail.com'];
const ps = $('List projects').all().map(function (i) { return i.json; });
const lr = $('Fetch project languages').all();
const EXCL = ['en', 'pst', 'ps', 'cus', 'pt_old', 'ja'];
const jobs = [];
for (let k = 0; k < ps.length; k++) {
  const p = ps[k];
  const b = lr[k] ? (lr[k].json.body !== undefined ? lr[k].json.body : lr[k].json) : null;
  const langs = (b && Array.isArray(b.languages)) ? b.languages : [];
  const en = langs.find(function (l) { return l.lang_iso === 'en'; });
  if (!en) { continue; }
  for (const l of langs) {
    if (EXCL.indexOf(l.lang_iso) !== -1) { continue; }
    jobs.push({ json: Object.assign({}, p, { mode: 'edits', iso: l.lang_iso, lang_id: l.lang_id, en_id: en.lang_id, lang_name: l.lang_name, linguists: LINGUISTS, match: [] }) });
  }
}
if (!jobs.length) { throw new Error('No project languages returned'); }
return jobs;

// For every language with linguist edits, look for the same English in every active project (incl. the same project).
const jobs = $('Build edit jobs').all().map(function (i) { return i.json; });
const res = $('Scan edits').all().map(function (i) { return i.json || {}; });
function norm(s) { return String(s || '').replace(/\s+/g, ' ').trim(); }
const byIso = {};
for (const r of res) { for (const row of (r.rows || [])) { (byIso[r.iso] = byIso[r.iso] || {})[norm(row.en)] = 1; } }
const out = [];
for (const j of jobs) {
  const set = byIso[j.iso];
  if (!set) { continue; }
  out.push({ json: Object.assign({}, j, { mode: 'match', linguists: [], match: Object.keys(set) }) });
}
if (!out.length) { out.push({ json: { mode: 'none' } }); }
return out;

const edits = $('Scan edits').all().map(function (i) { return i.json || {}; });
let matches = [];
try { matches = $('Scan matches').all().map(function (i) { return i.json || {}; }); } catch (e) { matches = []; }
let terms = [];
for (const it of $('Fetch glossary').all()) {
  const b = it.json.body !== undefined ? it.json.body : it.json;
  terms = terms.concat((b && (b.data || b.glossary_terms || b.terms)) || []);
}
const rules = $('Read style rules').all().map(function (i) { return i.json; });
const guides = (($('List style guides').first().json || {}).files) || [];
function slim(r) { return { mode: r.mode, project_id: r.project_id, project: r.project_name, iso: r.iso, lang: r.lang_name, rows: r.rows || [], archived_skipped: r.archived_skipped || 0, errors: r.errors || [], en_seen: r.en_seen, tgt_seen: r.tgt_seen }; }
return [{ json: {
  run_at: new Date().toISOString(),
  edits: edits.map(slim),
  matches: matches.filter(function (m) { return m.mode === 'match'; }).map(slim),
  glossary: terms,
  style_rules: rules,
  style_guides: guides
} }];
